import { expect, test, type Page } from '@playwright/test';
import { signUpRecipient } from './helpers';
import { chooseAndSave, jpegOf } from './image-picker-helpers';
import { sql } from './ops-helpers';

// Photos, not initials (owner, 15 Nov 2026): the dashboard's account button (top right) shows the
// person's photo when they have one, and their initial only when not. #209 fixed the page card and
// missed this button. The picture is generated by the test (a flat colour), never a real photo.

test.slow();

const accountButton = (page: Page) =>
  page.getByRole('main').getByRole('button', { name: /^Account:/ });
const chip = (page: Page) => accountButton(page).locator('.hat-menu__initial');

async function setName(handle: string, name: string) {
  await sql('UPDATE profiles SET display_name = $2 WHERE handle_lower = $1', [
    handle,
    name,
  ]);
}

test('the account button shows the initial without a photo, the photo once there is one', async ({
  page,
}, testInfo) => {
  const { handle } = await signUpRecipient(page, testInfo);
  await setName(handle, 'Saviour Eking');
  await page.goto('/dashboard');
  await expect(accountButton(page)).toContainText('Saviour Eking', {
    timeout: 20_000,
  });
  // No photo: the initial, no picture.
  await expect(chip(page)).toHaveText('S');
  await expect(chip(page).locator('img')).toHaveCount(0);
  const before = await chip(page).boundingBox();
  const buttonBefore = await accountButton(page).boundingBox();

  // The shared picker, as in photos-not-initials.spec.ts.
  await page.goto('/dashboard/settings');
  const card = page.locator('#photo');
  await chooseAndSave(page, card, 'Choose a photo', 'photo', {
    name: 'me.jpg',
    mimeType: 'image/jpeg',
    buffer: await jpegOf(600, 600, { r: 230, g: 120, b: 20 }),
  });
  await expect(
    card.getByRole('status').getByText('Photo saved.'),
  ).toBeVisible();

  await page.goto('/dashboard');
  const photo = chip(page).locator('img');
  await expect(photo).toHaveAttribute(
    'src',
    /\/v1\/avatars\/[0-9a-f-]+\/\d+\.webp$/,
    { timeout: 20_000 },
  );
  await expect
    .poll(() => photo.evaluate((img: HTMLImageElement) => img.naturalWidth))
    .toBeGreaterThan(0);
  // The picture replaces the initial at the same size and shape, so nothing moves.
  await expect(chip(page)).not.toContainText('S');
  expect(await chip(page).boundingBox()).toEqual(before);
  expect(await accountButton(page).boundingBox()).toEqual(buttonBefore);
  await expect(accountButton(page)).toHaveAccessibleName(
    'Account: Saviour Eking',
  );

  // The menu's own row for the page shows the same photo.
  await accountButton(page).click();
  await expect(
    page.getByRole('menu').getByRole('menuitem').first().locator('img'),
  ).toHaveCount(1);
});
